        List<List<int>> result = new List<List<int>>();
        List<int> items = new List<int>();
        Backtrack(nums, 0, result, items);

        return result;
    }

    private void Backtrack(List<int> nums, int idx, 
                    List<List<int>> result,
                    List<int> items) {

        result.Add(new List<int>(items));

        for(int i = idx; i < nums.Count; i++) {

            items.Add(nums[i]);
            Backtrack(nums, i + 1, result, items);

            items.RemoveAt(items.Count - 1);
        }

    }
}
